# Settings: SettingsDisplay (dark, Arabic, with the "keep?" dialog), SettingsDisplayLight (light, English),
# SettingsDrivers, Account, Projection.
from gen import *
W, H = 360, 225
# every area of section 8 (+ 12.3); areas bound to missing hardware (mobile network) do not appear
AREAS = [('wifi', 'واي فاي', 'Wi-Fi'), ('network', 'الشبكة', 'Network'), ('bluetooth', 'بلوتوث', 'Bluetooth'), ('monitor', 'الشاشات', 'Displays'), ('volume', 'الصوت', 'Sound'), ('battery', 'الطاقة', 'Power'),
    ('dock', 'سطح المكتب والمرسى', 'Desktop and dock'), ('workspaces', 'النوافذ ومساحات العمل', 'Windows and workspaces'), ('palette', 'المظهر', 'Appearance'), ('bell', 'الإشعارات', 'Notifications'), ('search', 'البحث', 'Search'),
    ('apps', 'التطبيقات', 'Apps'), ('mouse', 'الفأرة ولوحة اللمس', 'Mouse and touchpad'), ('keyboard', 'لوحة المفاتيح', 'Keyboard'), ('printer', 'الطابعات والماسحات', 'Printers and scanners'), ('colour', 'الألوان', 'Colour'),
    ('access', 'تسهيلات الاستخدام', 'Accessibility'), ('shield', 'الخصوصية والأمان', 'Privacy and security'), ('sharing', 'المشاركة', 'Sharing'), ('user', 'الحسابات', 'Accounts'), ('users', 'المستخدمون', 'Users'),
    ('language', 'المنطقة واللغة', 'Region and language'), ('clock', 'التاريخ والوقت', 'Date and time'), ('disk', 'التخزين', 'Storage'), ('chip', 'العتاد والتعريفات', 'Drivers and hardware'), ('update', 'التحديثات', 'Updates'),
    ('backup', 'النسخ الاحتياطي', 'Backup'), ('mesh', 'الترابط', 'Mesh'), ('spark', 'المساعد', 'Assistant'), ('cells', 'الخلايا والحاويات', 'Cells and containers'), ('sos', 'الطوارئ', 'Emergency'), ('device', 'حول النظام', 'About')]
def settings_side(active):
    return sidebar(L('أقسام الإعدادات', 'Settings areas'), searchbox(L('ابحث في الإعدادات', 'Search settings'), 'settings.search') + ''.join(navitem(i, L(a, e), 'settings.area', i == active) for i, a, e in AREAS), 72)
def settings(active, content, overlay=''):
    return appwindow(L('الإعدادات', 'Settings'), settings_side(active) + f'<main style="flex: 1; min-width: 0; padding: {s5} {s6}; box-sizing: border-box; overflow: hidden; display: flex; flex-direction: column; gap: {s4}">{content}</main>', overlay=overlay)

def display(dialog_open):
    def mon(x, y, w, h, n, name, sel=False, primary=False):
        lab = L(f'الشاشة {n}: {name}', f'Display {n}: {name}')
        return f'<button role="radio" aria-checked="{"true" if sel else "false"}"{act("display.select", lab)} aria-label="{plain(lab)}{L(" (الرئيسية)", " (main)") if primary else ""}"{"" if sel else " tabindex=\"-1\""} style="position: absolute; left: {g(x)}; top: {g(y)}; width: {g(w)}; height: {g(h)}; border-radius: {r_ctl}; background: {t.hover if sel else t.raised}; border: {RING if sel else HAIR} solid {t.acctext if sel else t.ctl}; box-sizing: border-box; display: flex; flex-direction: column; align-items: center; justify-content: center">{"<span style=\"font-size: " + f12 + "; font-weight: " + str(w6) + "\">" + L("الرئيسية", "Main") + "</span>" if primary else ""}<span style="font-family: {FF_TITLE}; font-size: {f24}; font-weight: {w7}; display: inline-flex; align-items: center; gap: {s1}">{ic("check", True) if sel else ""}{n}</span><span dir="{"rtl" if cx.rtl else "ltr"}" style="font-size: {f12}; color: {t.mute}">{tx(name)}</span></button>'
    # stage: the real position of the screens, therefore physical left-to-right (R2); DOM order by number (A35)
    stage = f'<div role="radiogroup" aria-label="{L("الشاشة المحدَّدة", "Selected display")}" style="position: relative; height: {g(36)}; border-radius: {r_ctl}; background: {t.ground}; border: {HAIR} solid {t.line}; direction: ltr">{mon(58, 4, 44, 28, 1, L("المدمجة 15.6″", "Built-in 15.6″"), True, True)}{mon(20, 6, 36, 24, 2, "Dell 24″")}{mon(104, 6, 36, 24, 3, "Dell 24″")}</div>'
    arr = card(cardhead(L('ترتيب الشاشات', 'Arrangement'), L('اسحب الشاشات لتطابق أماكنها على مكتبك. اختر شاشة لتغيير إعداداتها.', 'Drag the displays to match their place on your desk. Select one to change its settings.'),
        button(L('إظهار أرقام الشاشات', 'Show display numbers'), 'display.identify') + button(L('البحث عن شاشات', 'Look for displays'), 'display.detect')) + f'<div style="padding: {s4}">{stage}</div>')
    def mode(kind, title, text, on):
        return f'<button role="radio" aria-checked="{"true" if on else "false"}"{act("display.mode", title)}{"" if on else " tabindex=\"-1\""} style="flex: 1; padding: {s3}; border-radius: {r_card}; background: {t.hover if on else t.surface}; border: {RING if on else HAIR} solid {t.acctext if on else t.ctl}; box-sizing: border-box; display: flex; flex-direction: column; align-items: center; gap: {s1}; text-align: center">{picto(kind)}<span style="font-weight: {w6}; display: inline-flex; align-items: center; gap: {s1}">{ic("check", True) if on else ""}{tx(title)}</span><span style="font-size: {f12}; color: {t.mute}">{tx(text)}</span></button>'
    modes = card(cardhead(L('عند توصيل أكثر من شاشة', 'With more than one display')) + f'<div style="padding: {s4}">' + radiogroup(L('وضع العرض', 'Display mode'), mode('extend', L('توسيع', 'Extend'), L('سطح مكتب واحد على كل الشاشات', 'One desktop across all displays'), True)
        + mode('mirror', L('تكرار', 'Mirror'), L('الصورة نفسها على الشاشات المختارة', 'The same picture on the chosen displays'), False) + mode('first', L('شاشة واحدة فقط', 'Only one display'), L('إطفاء الشاشات الأخرى', 'The other displays are switched off'), False)) + '</div>')
    nl = f'<div style="display: flex; align-items: center; gap: {s2}">{switch(True, L("الضوء الليلي", "Night light"), "display.nightlight")}{ibtn(L("الضوء الليلي: الجدول ودرجة الدفء", "Night light: schedule and warmth"), "forward", "display.nightlight.more")}</div>'
    glob = card(row(L('الضوء الليلي', 'Night light'), L('ألوان أدفأ من الغروب حتى الشروق', 'Warmer colours from sunset to sunrise'), nl) + row(L('تذكّر أماكن النوافذ لكل شاشة', 'Remember window positions per display'), L('تعود النوافذ إلى شاشتها عند إعادة توصيلها', 'Windows return to their display when it is connected again'), switch(True, L('تذكّر أماكن النوافذ لكل شاشة', 'Remember window positions per display'), 'display.remember'))
        + row(L('إظهار الشريط', 'Show the bar'), '', select(L('على كل الشاشات', 'On all displays'), L('إظهار الشريط', 'Show the bar'), 'display.bar')) + row(L('عند إغلاق الغطاء مع شاشة خارجية', 'Lid closed with an external display'), '', select(L('متابعة العمل على الشاشة الخارجية', 'Keep working on the external display'), L('عند إغلاق الغطاء مع شاشة خارجية', 'Lid closed with an external display'), 'display.lid'), True))
    numb = f'<span style="width: {tgt}; height: {tgt}; flex: none; border-radius: {r_ctl}; border: {HAIR} solid {t.ctl}; box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center; font-family: {FF_TITLE}; font-size: {f16}; font-weight: {w7}">1</span>'
    head = f'<div style="padding: {s4}; border-bottom: {HAIR} solid {t.line}; display: flex; align-items: center; gap: {s3}">{numb}<div style="flex: 1">{h2(L("الشاشة المدمجة 15.6″", "Built-in display 15.6″"))}{sub(L("3840 × 2160 · شاشة داخلية", "3840 × 2160 · internal display"))}</div></div>'
    sel = card(head + row(L('الشاشة الرئيسية', 'Main display'), L('يظهر عليها الشريط وتُفتح فيها التطبيقات الجديدة وشاشة تسجيل الدخول', 'Shows the bar, new apps and the sign-in screen'), badge(L('هذه هي الشاشة الرئيسية', 'This is the main display'), 'ok', 'check'))
        + row(L('الدقّة', 'Resolution'), '', select(L('3840 × 2160 (موصى بها)', '3840 × 2160 (recommended)'), L('الدقّة', 'Resolution'), 'display.resolution')) + row(L('حجم العناصر', 'Size of elements'), L('يُقترح حسب كثافة الشاشة', 'Suggested from the pixel density'), select(L('200% (موصى به)', '200% (recommended)'), L('حجم العناصر', 'Size of elements'), 'display.scale'))
        + row(L('معدّل التحديث', 'Refresh rate'), '', select('60 Hz', L('معدّل التحديث', 'Refresh rate'), 'display.refresh')) + row(L('الاتجاه', 'Orientation'), '', select(L('أفقي', 'Landscape'), L('الاتجاه', 'Orientation'), 'display.orientation'))
        + row('HDR', L('غير مدعوم على هذه الشاشة', 'Not supported by this display'), switch(False, 'HDR', 'display.hdr', 'disabled')) + row(L('ملف الألوان', 'Colour profile'), '', select(L('تلقائي (sRGB)', 'Automatic (sRGB)'), L('ملف الألوان', 'Colour profile'), 'display.profile'))
        + row(L('السطوع', 'Brightness'), '', slider(L('سطوع الشاشة المدمجة', 'Brightness of the built-in display'), 78, 'display.brightness', width=g(60)), True))
    content = h1(L('الشاشات', 'Displays')) + f'<div style="display: flex; gap: {s4}; align-items: flex-start"><div style="width: {g(160)}; flex: none; display: flex; flex-direction: column; gap: {s4}">{arr}{modes}{glob}</div><div style="flex: 1; min-width: 0">{sel}</div></div>'
    dlg = ''
    if dialog_open:
        live = f'<div role="timer" aria-live="polite" style="display: flex; flex-direction: column; gap: {s2}"><div style="font-weight: {w6}">{tx("تُلغى تلقائياً خلال 15 ثانية")}</div>{progress("الوقت المتبقّي", 100)}</div>'
        dlg = dialog('هل تريد الاحتفاظ بهذه الإعدادات؟', 'تغيّر وضع العرض إلى «توسيع». إن لم تختر، يعود الوضع السابق.', button('أحتاج وقتاً أكثر', 'display.keep.more', 'quiet') + button('تراجع', 'display.revert') + button('احتفاظ', 'display.keep', 'primary'), live=live)
    return settings('monitor', content, dlg)
begin('SettingsDisplay.dc.html')
out('Ultar OS – إعدادات الشاشات', W, H, display(True), 'Einstellungen · Anzeige · dunkel · Arabisch (mit Rückfrage „Behalten?“ 15 s)', 2)
begin('SettingsDisplayLight.dc.html', 'light', False)
out('Ultar OS – display settings', W, H, display(False), 'Einstellungen · Anzeige · hell · Englisch', 2)

# ---------- drivers and hardware (shared with the installer step 7) ----------
DEVICES = [('monitor', 'بطاقة الرسوميات', 'Intel Arc (مدمجة)', 'ultar-gfx-intel', 'ok', 'يعمل', 'تسريع كامل'), ('wifi', 'واي فاي', 'Intel AX211', 'ultar-wifi-iwl', 'ok', 'يعمل', ''), ('cable', 'الشبكة السلكية', 'Realtek RTL8125', 'ultar-net-r8125', 'ok', 'يعمل', ''),
    ('volume', 'الصوت', 'Realtek ALC295', 'ultar-audio-hda', 'ok', 'يعمل', ''), ('bluetooth', 'بلوتوث', 'Intel AX211', 'ultar-bt-intel', 'ok', 'يعمل', ''), ('mouse', 'لوحة اللمس', 'ELAN I2C', 'ultar-input-i2c', 'ok', 'يعمل', ''),
    ('video', 'الكاميرا', 'USB UVC', 'ultar-cam-uvc', 'warn', 'يعمل بقيود', 'الدقّة القصوى 720p'), ('lock', 'قارئ بصمة الإصبع', 'Goodix 27C6', '', 'danger', 'بلا تعريف', 'لا تسجيل دخول بالبصمة')]
def device_table(prefix, settings_mode):
    hd = f'<div role="row" style="display: flex; gap: {s4}; padding: {s2} {s4}; font-size: {f12}; color: {t.mute}; border-bottom: {HAIR} solid {t.line}"><span role="columnheader" style="flex: 3">الجهاز</span><span role="columnheader" style="flex: 2">التعريف</span><span role="columnheader" style="flex: 2">الحالة</span><span role="columnheader" style="flex: 3">{"الإجراءات" if settings_mode else "البدائل والاختبار"}</span></div>'
    rows = ''
    for n, (icon, kind, model, drv, st, st_text, more) in enumerate(DEVICES):
        if drv:
            ctl = select('الموصى به', f'تعريف {kind}', prefix + '.alt') + (button('استرجاع السابق', prefix + '.rollback', 'quiet', name=f'{kind}: استرجاع التعريف السابق') if settings_mode else button('اختبار', prefix + '.test', 'quiet', name=f'{kind}: اختبار'))
            drvtxt = f'<span style="font-family: {FF_MONO}; font-size: {f12}">{ltr(drv)}</span>'
        else:
            ctl = button('حفظ مخطّط العتاد', prefix + '.plan', icon='download', name=f'{kind}: حفظ مخطّط العتاد')
            drvtxt = f'<span style="color: {t.mute}">{NA}</span>'
        stb = badge(st_text, st, {'ok': 'check', 'warn': 'warning', 'danger': 'error'}[st])
        rows += f'<div role="row" style="display: flex; align-items: center; gap: {s4}; min-height: {s7}; padding: {s1} {s4}; box-sizing: border-box; border-bottom: {"none" if n == len(DEVICES) - 1 else HAIR + " solid " + t.line}"><div role="cell" style="flex: 3; display: flex; align-items: center; gap: {s3}"><span style="display: inline-flex; color: {t.mute}">{ic(icon)}</span><div><div style="font-weight: {w5}">{tx(kind)}</div>{sub(model)}</div></div><div role="cell" style="flex: 2">{drvtxt}</div><div role="cell" style="flex: 2"><div style="display: flex">{stb}</div>{sub(more, t.danger if st == "danger" else None) if more else ""}</div><div role="cell" style="flex: 3; display: flex; gap: {s2}; justify-content: flex-end">{ctl}</div></div>'
    return card(f'<div role="table" aria-label="الأجهزة المكتشفة">{hd}{rows}</div>')
def driverless_hint():
    return hint('danger', 'جهاز واحد بلا تعريف: قارئ بصمة الإصبع (Goodix 27C6)', 'النتيجة: لن يعمل تسجيل الدخول بالبصمة – استخدم كلمة المرور أو الرمز PIN. احفظ مخطّط العتاد لنبني له تعريفاً.')
begin('SettingsDrivers.dc.html')
fw = card(row('تحديثات البرامج الثابتة', 'آخر بحث: اليوم 09:10 · لا تحديثات', f'<div style="display: flex; gap: {s2}">{button("البحث عن تحديثات", "drivers.fw.check")}{button("تحديث من USB", "drivers.fw.usb")}</div>', icon='update') + row('الاختبار الذاتي', 'يفحص الذاكرة والقرص والشاشة والصوت والشبكة', button('بدء الاختبار', 'drivers.selftest'), True, icon='chip'))
out('Ultar OS – العتاد والتعريفات', W, H, settings('chip', h1('العتاد والتعريفات') + driverless_hint() + device_table('drivers', True) + fw), 'Einstellungen · Treiber & Hardware (§8)', 2)

begin('Account.dc.html')
purpose = 'حساب Ultar اختياري. يلزم فقط للمكالمات برقم Ultar، و VPN من Ultar، والنسخ الاحتياطي، والترابط عبر الإنترنت، والتطبيقات المدفوعة. المتجر والتحديثات تعمل من دونه.'
out_card = card(cardhead('غير مسجَّل الدخول', purpose) + f'<div style="padding: {s4}; display: flex; flex-direction: column; gap: {s3}">{field("اسم المستخدم", "account.username", value="anas", direction="ltr")}<div style="display: flex; align-items: flex-end; gap: {s2}">{field("كلمة المرور", "account.password", kind="password", value="••••••••••")}{ibtn("إظهار كلمة المرور", "eye", "account.show")}</div><div>{sub("قوّة كلمة المرور: قويّة")}{progress("قوّة كلمة المرور", 80)}</div><div style="display: flex; gap: {s2}">{button("تسجيل الدخول", "account.signin", "primary")}{button("إنشاء حساب", "account.create")}</div>{field("عنوان الخادم", "account.server", value="ultar.code-craft.tech", direction="ltr")}</div>', label='الحالة: غير مسجَّل الدخول')
others = card(cardhead('حالات أخرى للبطاقة') + f'<div style="padding: {s4}; display: flex; flex-direction: column; gap: {s2}">{hint("warn", "غير متصل", "تُعرض آخر حالة معروفة ولا يضيع شيء.", icon="offline")}{hint("danger", "تعذّر تسجيل الدخول", "كلمة المرور غير صحيحة. بقيت 3 محاولات.")}{hint("danger", "الحساب مقفل مؤقتاً", "محاولات خاطئة كثيرة. حاول بعد 15 دقيقة.")}</div>')
qr = f'<div role="img" aria-label="رمز QR لرقم Ultar (عنصر نائب)" style="width: {g(24)}; height: {g(24)}; flex: none; border-radius: {r_ctl}; border: {HAIR} dashed {t.ctl}; box-sizing: border-box; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: {s1}; color: {t.mute}; font-size: {f12}">{ic("qr")}<span>{tx("رمز QR")}</span></div>'
number = f'<div style="padding: {s4}; display: flex; flex-direction: column; gap: {s3}; border-bottom: {HAIR} solid {t.line}"><div style="display: flex; align-items: center; gap: {s4}">{qr}<div style="flex: 1">{sub("رقم Ultar")}<div style="font-family: {FF_MONO}; font-size: {f24}; font-weight: {w7}">{ltr("UOS-XXXX-XXXX")}</div>{sub("شاركه ليتّصل بك الآخرون عبر Ultar.")}</div></div><div style="display: flex; gap: {s2}">{button("نسخ", "account.copy", icon="copy", name="نسخ رقم Ultar")}{button("تكبير رمز QR", "account.qr", icon="qr")}</div></div>'
who = f'<div style="padding: {s4}; display: flex; align-items: center; gap: {s3}; border-bottom: {HAIR} solid {t.line}"><span style="width: {s7}; height: {s7}; flex: none; border-radius: {r_round}; background: {t.raised}; border: {HAIR} solid {t.ctl}; box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center">{ic("cloud")}</span><div style="flex: 1">{h2("anas")}{sub("ultar.code-craft.tech")}</div>{badge("مسجَّل الدخول", "ok", "check")}</div>'
services = ''.join(row(a, b, switch(on, a, 'account.service'), last=(n == 4)) for n, (a, b, on) in enumerate([('استقبال مكالمات Ultar', 'يرنّ هذا الجهاز عند الاتصال برقمك · مُطفأ افتراضياً', False), ('VPN من Ultar', 'اتصال مشفّر بنقرة واحدة', True), ('مشتريات المتجر', 'التطبيقات المدفوعة والتراخيص', True), ('النسخ الاحتياطي', 'نسخة مشفّرة في حسابك', False), ('الترابط عبر الإنترنت', 'ربط أجهزتك خارج الشبكة المحلّية', True)]))
adv = f'<div style="padding: {s4}; display: flex; flex-wrap: wrap; gap: {s2}; border-top: {HAIR} solid {t.line}">{button("تغيير كلمة المرور", "account.changepw")}{button("تسجيل الخروج", "account.signout")}<span style="flex: 1"></span>{button("حذف الحساب", "account.delete", "danger", icon="trash")}</div>'
in_card = card(who + number + services + adv, label='الحالة: مسجَّل الدخول')
def dev(icon, name, text, this=False):
    ctl = badge('هذا الجهاز · مسجَّل', 'ok', 'check') if this else button('تسجيل الخروج منه', 'account.device.signout', 'quiet', name=f'{name}: تسجيل الخروج منه') + button('إزالة', 'account.device.remove', 'danger', name=f'{name}: إزالة')
    return f'<li style="padding: {s2} {s4}; display: flex; flex-direction: column; gap: {s2}; border-bottom: {HAIR} solid {t.line}"><div style="display: flex; align-items: center; gap: {s3}"><span style="display: inline-flex; color: {t.mute}">{ic(icon)}</span><div style="flex: 1"><div style="font-weight: {w5}">{tx(name)}</div>{sub(text)}</div></div><div style="display: flex; gap: {s2}; justify-content: flex-end">{ctl}</div></li>'
devices = card(cardhead('أجهزتي', 'الأجهزة المسجَّلة في حسابك') + f'<ul role="list">{dev("device", "ultar-pc", "حاسوب محمول · نشط الآن", True)}{dev("phone", "KM One", "هاتف · آخر ظهور اليوم 14:20")}{dev("monitor", "ultar-office", "حاسوب مكتبي · آخر ظهور 20 تشرين الثاني")}</ul>')
crumb = f'<div style="display: flex; align-items: center; gap: {s2}">{ibtn("رجوع إلى الحسابات", "back", "account.back")}{h1("حساب Ultar")}</div>'
out('Ultar OS – حساب Ultar', W, H, settings('user', crumb + f'<div style="display: flex; gap: {s4}; align-items: flex-start"><div style="width: {g(80)}; flex: none">{out_card}</div><div style="flex: 1; min-width: 0">{in_card}</div><div style="width: {g(84)}; flex: none; display: flex; flex-direction: column; gap: {s4}">{devices}{others}</div></div>'), 'Einstellungen · Konten · Ultar-Konto (§12.1)', 2)

begin('Projection.dc.html')
def big(kind, label, on):
    return f'<button role="radio" aria-checked="{"true" if on else "false"}"{act("projection.mode", label)}{"" if on else " tabindex=\"-1\""} style="flex: 1; height: {g(36)}; border-radius: {r_card}; background: {t.hover if on else t.raised}; border: {RING if on else HAIR} solid {t.acctext if on else t.ctl}; box-sizing: border-box; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: {s3}">{picto(kind)}<span style="font-weight: {w6}; display: inline-flex; align-items: center; gap: {s1}">{ic("check", True) if on else ""}{tx(label)}</span></button>'
keys = f'<div style="font-size: {f12}; color: {t.mute}; display: flex; align-items: center; gap: {s2}">{key("Super")}{key("P")}<span>للتنقّل</span>{key("Enter")}<span>للتأكيد</span>{key("Esc")}<span>للإلغاء</span></div>'
